return $input.all().map((item, index) => {
  const body = item.json.body;

  const ticket =
    body && typeof body === "object" &&
    !Array.isArray(body)
      ? body
      : {};

  return {
    json: {
      ticket_id: ticket.ticket_id,
      customer_name: ticket.customer_name,
      category: ticket.category,
      message: ticket.message
    },
    pairedItem: { item: index }
  };
});

const teamMap = {
  billing: "Finance",
  technical: "Technical Support",
  delivery: "Logistics",
  other: "Customer Support"
};

return $input.all().map((item, index) => {
  const ticket = item.json;

  const assignedTeam =
    teamMap[ticket.category] ?? "Customer Support";

  return {
    json: {
      ...ticket,
      assigned_team: assignedTeam,
      ticket_status: "routed"
    },
    pairedItem: { item: index }
  };
});

const incoming = $("Assign Team").first().json;
const existing = $input.first().json;

const exists =
  typeof existing.ticket_id === "string" &&
  existing.ticket_id === incoming.ticket_id;

let decision = "new";

if (exists) {
  const sameContent =
    existing.customer_name === incoming.customer_name &&
    existing.category === incoming.category &&
    existing.message === incoming.message;

  decision = sameContent ? "replay" : "conflict";
}

return [{
  json: {
    ...incoming,
    decision,
    existing_record_found: exists
  }
}];

const allowedCategories = [
  "billing",
  "technical",
  "delivery",
  "other"
];

// This lab handles one ticket per webhook request.
const ticket = $("Prepare Ticket").first().json;

return $input.all().map((item, index) => {
  const response = item.json;
  const errors = [];

  let parsed = null;
  let category = null;

  if (response.done !== true) {
    errors.push("Incomplete AI response");
  }

  if (
    typeof response.response !== "string" ||
    !response.response.trim()
  ) {
    errors.push("Missing AI response");
  } else {
    try {
      parsed = JSON.parse(response.response);
    } catch {
      errors.push("Malformed JSON");
    }
  }

  if (
    parsed === null ||
    typeof parsed !== "object" ||
    Array.isArray(parsed)
  ) {
    if (!errors.length) {
      errors.push("AI output must be an object");
    }
  } else if (typeof parsed.category !== "string") {
    errors.push("Missing category");
  } else {
    category = parsed.category.trim().toLowerCase();

    if (!allowedCategories.includes(category)) {
      errors.push("Unsupported category");
    }
  }

  const aiValid = errors.length === 0;

  return {
    json: {
      ticket_id: ticket.ticket_id,
      customer_name: ticket.customer_name,
      message: ticket.message,
      category: aiValid ? category : null,
      ai_valid: aiValid,
      ai_errors: errors,
      classification_source: "ollama_gemma3_4b"
    },
    pairedItem: { item: index }
  };
});

const testCategoryOverride = null;

return $input.all().map((item, index) => {
  const ticket = item.json;
  const message = String(ticket.message ?? "").toLowerCase();
  const category = testCategoryOverride ?? ticket.category;

  // Independent, deliberately limited warning signals.
  const signals = [];

  if (/\b(password|sign in|log in|login|account access)\b/.test(message)) {
    signals.push("technical");
  }

  if (/\b(charged|debited|refund|invoice|payment)\b/.test(message)) {
    signals.push("billing");
  }

  if (/\b(package|parcel|tracking|shipment|shipping)\b/.test(message)) {
    signals.push("delivery");
  }

  const reasons = [];

  if (signals.length > 1) {
    reasons.push("Message contains multiple category signals");
  } else if (
    signals.length === 1 &&
    signals[0] !== category
  ) {
    reasons.push("AI category conflicts with message signal");
  }

  if (/\b(suspicious|hacked|breach|unauthorized|unauthorised)\b/.test(message)) {
    reasons.push("Potential security-sensitive inquiry");
  }

  return {
    json: {
      ...ticket,
      category,
      requires_review: reasons.length > 0,
      review_reasons: reasons
    },
    pairedItem: { item: index }
  };
});

const incoming = $("Prepare Review Record").first().json;
const existing = $input.first().json;

let result;

if (!existing.ticket_id) {
  result = "new";
} else if (existing.ticket_id !== incoming.ticket_id) {
  result = "conflict";
} else {
  const sameCustomer =
    existing.customer_name === incoming.customer_name;

  const sameMessage =
    existing.message === incoming.message;

  if (sameCustomer && sameMessage) {
    result = "replay";
  } else {
    result = "conflict";
  }
}

return [{
  json: {
    ticket_id: incoming.ticket_id,
    submission_result: result,
    existing_review_status:
      existing.review_status ?? null
  }
}];

const incoming = $input.first().json;
const required = ["ticket_id", "customer_name", "message"];

const errors = required.filter(field =>
  typeof incoming[field] !== "string" ||
  incoming[field].trim() === ""
);

return [{
  json: {
    ...incoming,
    identity_valid: errors.length === 0,
    identity_errors: errors
  }
}];

const incoming = $("Prepare Ticket").first().json;
const main = $("Find Existing Main Ticket").first().json;
const review = $("Find Existing Review Ticket").first().json;

const mainExists = main.ticket_id === incoming.ticket_id;
const reviewExists = review.ticket_id === incoming.ticket_id;

const teamMap = {
  billing: "Finance",
  technical: "Technical Support",
  delivery: "Logistics",
  other: "Customer Support"
};

function sameSubmission(record) {
  return (
    record.customer_name === incoming.customer_name &&
    record.message === incoming.message
  );
}

function validPromotedPair() {
  const category = String(
    review.reviewed_category ?? ""
  ).trim().toLowerCase();

  return (
    review.review_status === "promoted" &&
    Object.hasOwn(teamMap, category) &&
    main.customer_name === review.customer_name &&
    main.message === review.message &&
    main.category === category &&
    main.assigned_team === teamMap[category]
  );
}

let result = "new";
let source = null;
let status = null;

if (mainExists && reviewExists) {
  source = "both";
  status = review.review_status ?? null;

  if (validPromotedPair()) {
    result = sameSubmission(review)
      ? "replay"
      : "conflict";
  } else {
    result = "inconsistent";
  }

} else if (mainExists) {
  source = "main";
  status = main.ticket_status ?? null;

  result = sameSubmission(main)
    ? "replay"
    : "conflict";

} else if (reviewExists) {
  source = "review";
  status = review.review_status ?? null;

  result = sameSubmission(review)
    ? "replay"
    : "conflict";
}

return [{
  json: {
    ...incoming,
    submission_result: result,
    existing_source: source,
    existing_status: status
  }
}];

